DROP TABLE IF EXISTS `student_grades`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_grades` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint(20) unsigned NOT NULL,
  `major_subject_id` bigint(20) unsigned NOT NULL,
  `academic_year_id` bigint(20) unsigned NOT NULL,
  `score` varchar(50) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_grades_student_major_subject_year_unique` (`student_id`,`major_subject_id`,`academic_year_id`),
  KEY `student_grades_student_id_index` (`student_id`),
  KEY `student_grades_major_subject_id_foreign` (`major_subject_id`),
  KEY `student_grades_academic_year_id_foreign` (`academic_year_id`),
  CONSTRAINT `student_grades_academic_year_id_foreign` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_grades_major_subject_id_foreign` FOREIGN KEY (`major_subject_id`) REFERENCES `major_subjects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_grades_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=72705 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
