--
-- Table structure for table `student_personal`
--

DROP TABLE IF EXISTS `student_personal`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_personal` (
  `student_id` bigint(20) unsigned NOT NULL,
  `first_name` varchar(255) NOT NULL DEFAULT '',
  `father_name` varchar(255) NOT NULL DEFAULT '',
  `grandfather_name` varchar(255) NOT NULL DEFAULT '',
  `surname` varchar(255) NOT NULL DEFAULT '',
  `gender_id` bigint(20) unsigned DEFAULT NULL,
  `gender` varchar(255) NOT NULL DEFAULT '',
  `birth_date` date DEFAULT NULL,
  `birth_place` varchar(255) NOT NULL DEFAULT '',
  `mother_full_name` varchar(255) NOT NULL DEFAULT '',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`student_id`),
  KEY `student_personal_gender_id_foreign` (`gender_id`),
  KEY `student_personal_created_by_foreign` (`created_by`),
  KEY `student_personal_updated_by_foreign` (`updated_by`),
  CONSTRAINT `student_personal_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_personal_gender_id_foreign` FOREIGN KEY (`gender_id`) REFERENCES `genders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_personal_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_personal_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

